import React, { useState, useEffect, useCallback } from 'react';
import {
    Box,
    Typography,
    TextField,
    Button,
    List,
    ListItem,
    ListItemAvatar,
    Avatar,
    ListItemText,
    IconButton,
    CircularProgress,
    Alert,
    Divider,
    Paper
} from '@mui/material';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';
import SendIcon from '@mui/icons-material/Send';
import { commentaireService } from '../../services/commentaireService';
import { Commentaire } from '../../types';

interface CommentListProps {
    publicationId: number;
    currentUserId: number;
}

const CommentList: React.FC<CommentListProps> = ({ publicationId, currentUserId }) => {
    const [comments, setComments] = useState<Commentaire[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [newComment, setNewComment] = useState('');
    const [sending, setSending] = useState(false);
    const [editingId, setEditingId] = useState<number | null>(null);
    const [editText, setEditText] = useState('');

    // Charger les commentaires - enveloppé avec useCallback
    const loadComments = useCallback(async () => {
        setLoading(true);
        try {
            const response = await commentaireService.getByPublicationId(publicationId);
            setComments(response.data);
            setError(null);
        } catch (err) {
            setError("Erreur lors du chargement des commentaires");
            console.error(err);
        } finally {
            setLoading(false);
        }
    }, [publicationId]); 

    useEffect(() => {
        loadComments();
    }, [publicationId, loadComments]); 

    // Ajouter un commentaire
    const handleAddComment = async () => {
        if (!newComment.trim()) return;
        
        setSending(true);
        try {
            await commentaireService.ajouter(currentUserId, publicationId, newComment);
            setNewComment('');
            await loadComments();
        } catch (err) {
            setError("Erreur lors de l'ajout du commentaire");
        } finally {
            setSending(false);
        }
    };

    // Modifier un commentaire
    const handleEdit = async (commentId: number) => {
        if (!editText.trim()) return;
        
        try {
            await commentaireService.modifier(commentId, editText);
            setEditingId(null);
            setEditText('');
            await loadComments();
        } catch (err) {
            setError("Erreur lors de la modification");
        }
    };

    // Supprimer un commentaire
    const handleDelete = async (commentId: number) => {
        if (window.confirm('Voulez-vous vraiment supprimer ce commentaire ?')) {
            try {
                await commentaireService.supprimer(commentId);
                await loadComments();
            } catch (err) {
                setError("Erreur lors de la suppression");
            }
        }
    };

    // Formater la date
    const formatDate = (dateStr: string) => {
        const date = new Date(dateStr);
        const now = new Date();
        const diff = now.getTime() - date.getTime();
        
        if (diff < 60000) return 'à l\'instant';
        if (diff < 3600000) return `il y a ${Math.floor(diff / 60000)} min`;
        if (diff < 86400000) return `il y a ${Math.floor(diff / 3600000)} h`;
        if (diff < 604800000) return `il y a ${Math.floor(diff / 86400000)} j`;
        
        return date.toLocaleDateString('fr-FR');
    };

    return (
        <Paper sx={{ p: 2, mt: 2 }}>
            <Typography variant="h6" gutterBottom>
                Commentaires ({comments.length})
            </Typography>
            
            <Divider sx={{ mb: 2 }} />
            
            {error && (
                <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>
                    {error}
                </Alert>
            )}
            
            {/* Formulaire d'ajout */}
            <Box display="flex" gap={1} mb={3}>
                <TextField
                    fullWidth
                    size="small"
                    placeholder="Écrire un commentaire..."
                    value={newComment}
                    onChange={(e) => setNewComment(e.target.value)}
                    onKeyPress={(e) => e.key === 'Enter' && handleAddComment()}
                    disabled={sending}
                />
                <Button
                    variant="contained"
                    onClick={handleAddComment}
                    disabled={sending || !newComment.trim()}
                    sx={{ minWidth: 80 }}
                >
                    {sending ? <CircularProgress size={24} /> : <SendIcon />}
                </Button>
            </Box>
            
            {/* Liste des commentaires */}
            {loading ? (
                <Box display="flex" justifyContent="center" py={4}>
                    <CircularProgress />
                </Box>
            ) : comments.length === 0 ? (
                <Typography color="text.secondary" textAlign="center" py={4}>
                    Aucun commentaire pour cette publication
                </Typography>
            ) : (
                <List sx={{ p: 0 }}>
                    {comments.map((comment) => {
                        const avatarUrl = comment.photo_profil
                            ? `http://localhost:8080/Icons/${comment.photo_profil}`
                            : '/icons/green.jpg';
                        const isOwner = comment.utilisateur_id === currentUserId;
                        const isEditing = editingId === comment.id;
                        
                        return (
                            <React.Fragment key={comment.id}>
                                <ListItem
                                    alignItems="flex-start"
                                    secondaryAction={
                                        isOwner && !isEditing && (
                                            <Box>
                                                <IconButton
                                                    edge="end"
                                                    onClick={() => {
                                                        setEditingId(comment.id);
                                                        setEditText(comment.texte);
                                                    }}
                                                    size="small"
                                                >
                                                    <EditIcon fontSize="small" />
                                                </IconButton>
                                                <IconButton
                                                    edge="end"
                                                    onClick={() => handleDelete(comment.id)}
                                                    size="small"
                                                    color="error"
                                                >
                                                    <DeleteIcon fontSize="small" />
                                                </IconButton>
                                            </Box>
                                        )
                                    }
                                >
                                    <ListItemAvatar>
                                        <Avatar src={avatarUrl} />
                                    </ListItemAvatar>
                                    
                                    {isEditing ? (
                                        <Box sx={{ flex: 1, display: 'flex', gap: 1 }}>
                                            <TextField
                                                fullWidth
                                                size="small"
                                                value={editText}
                                                onChange={(e) => setEditText(e.target.value)}
                                                autoFocus
                                            />
                                            <Button
                                                size="small"
                                                variant="contained"
                                                onClick={() => handleEdit(comment.id)}
                                            >
                                                Enregistrer
                                            </Button>
                                            <Button
                                                size="small"
                                                onClick={() => setEditingId(null)}
                                            >
                                                Annuler
                                            </Button>
                                        </Box>
                                    ) : (
                                        <ListItemText
                                            primary={
                                                <Typography variant="subtitle2" component="span">
                                                    @{comment.pseudo}
                                                    <Typography
                                                        component="span"
                                                        variant="caption"
                                                        color="text.secondary"
                                                        sx={{ ml: 1 }}
                                                    >
                                                        {formatDate(comment.date)}
                                                    </Typography>
                                                </Typography>
                                            }
                                            secondary={
                                                <Typography variant="body2" color="text.primary">
                                                    {comment.texte}
                                                </Typography>
                                            }
                                        />
                                    )}
                                </ListItem>
                                <Divider variant="inset" component="li" />
                            </React.Fragment>
                        );
                    })}
                </List>
            )}
        </Paper>
    );
};

export default CommentList;
